<script setup lang="ts">
import { computed, ref } from 'vue'
import { IconArrowRight, IconCheck, IconClose, IconQuestionCircle, IconRelation, IconFile } from '@arco-design/web-vue/es/icon'
import type { RecordValue } from '@/api/workbench'
import { rows, record, text, texts, friendly, number, formatValue, operatorLabels, featureNames, truthLabel } from '@/services/presentation'
import { evaluationCandidates, pathsFor, humanReason, factDescription, normalGateClosed } from '@/services/analysis'
import { nameOf, sourcesFor, expressionText, labelMap } from '@/services/knowledge'
import SemanticGraph from '@/components/graphs/SemanticGraph.vue'
const props = defineProps<{ result: RecordValue; frame: RecordValue; knowledge: RecordValue; names: Map<string, string>; selectedCandidateId: string; focusObsId: string; rootkgd: boolean }>()
const emit = defineEmits<{ candidate: [id: string]; focus: [id: string] }>()
const showOtherCandidates = ref(false)
const candidates = computed(() => evaluationCandidates(props.result))
const supported = computed(() => candidates.value.filter((c) => c.eligible_for_ranking === true))
const visibleCandidates = computed(() => supported.value.length && !showOtherCandidates.value ? supported.value : candidates.value)
const selected = computed(() => candidates.value.find((c) => c.candidate_id === props.selectedCandidateId) ?? candidates.value[0] ?? null)
const checks = computed(() => rows(selected.value?.expectation_checks))
const facts = computed(() => rows(props.result.grounded_facts))
const paths = computed(() => pathsFor(props.result, selected.value))
const costs = computed(() => record(selected.value?.scoring_details))
const supportIds = computed(() => texts(selected.value?.support_obs_ids))
const missingIds = computed(() => [...new Set(checks.value.flatMap((c) => texts(c.missing_predicate_ids)))])
const conflictIds = computed(() => [...new Set(checks.value.flatMap((c) => texts(c.conflicting_fact_ids)))])
const topRankCount = computed(() => supported.value.filter((candidate) => candidate.rank === supported.value[0]?.rank && candidate.rank !== undefined).length)
const isPattern = computed(() => record(props.frame.task).target_role === 'pattern_family')
const completeChecks = computed(() => checks.value.filter((c) => c.selected_signature_value === true || c.observed_value === true))
const activeGraphIds = computed(() => [...texts(selected.value?.active_hypothesis_world_entities), ...checks.value.map((c) => text(c.pattern_id))])
const graphNames = computed(() => labelMap(props.knowledge))
const pathGroups = computed(() => {
  const groups = new Map<string, RecordValue[]>()
  paths.value.forEach((path, index) => { const key = text(path.joint_proof_id, `path-${index}`); groups.set(key, [...(groups.get(key) ?? []), path]) })
  return [...groups.values()]
})
function candidateName(candidate: RecordValue) { return props.names.get(text(candidate.candidate_id)) ?? friendly(candidate.candidate_name, '候选解释') }
function conditionName(id: unknown) { return props.names.get(text(id)) ?? nameOf(props.knowledge, id, '观测条件') }
function checkFacts(check: RecordValue) {
  return texts(check.predicate_ids).map((id) => facts.value.find((f) => f.predicate_id === id) ?? { predicate_id: id, value: null, actual_values: [], source_obs_ids: [] })
}
function factFocused(fact: RecordValue) { return texts(fact.source_obs_ids).includes(props.focusObsId) }
function focusFact(fact: RecordValue) { const id = texts(fact.source_obs_ids)[0]; if (id) emit('focus', id) }
function conditionExpected(fact: RecordValue) {
  const definition = rows(props.knowledge.observable_definitions).find((d) => d.predicate_id === fact.predicate_id)
  const comparison = definition ?? record(fact.predicate_check)
  return `${operatorLabels[text(comparison.op)] ?? text(comparison.op)} ${formatValue(comparison.operand)}`
}
function checkExpression(check: RecordValue) {
  const pattern = rows(props.knowledge.pattern_definitions).find((p) => p.pattern_id === check.pattern_id)
  return pattern ? expressionText(pattern.body, graphNames.value) : ''
}
function checkSources(check: RecordValue) {
  const rule = rows(props.knowledge.expectation_rules).find((r) => r.rule_id === check.rule_id)
  return rule ? sourcesFor(props.knowledge, rule) : []
}
function routeNodes(path: RecordValue) {
  const ids = texts(path.nodes), directNames = Array.isArray(path.node_names) ? texts(path.node_names) : []
  return ids.flatMap((id, index) => {
    const label = props.names.get(id) ?? directNames[index]
    if (!label || id.includes(':definition') || id.startsWith('expectation:') || id.startsWith('effect:') || id.startsWith('rule:')) return []
    return [{ id, label: friendly(label), isCandidate: id === selected.value?.candidate_id }]
  })
}
function pathObservation(path: RecordValue) {
  const ids = texts(path.support_obs_ids)
  return rows(props.frame.observations).filter((o) => ids.includes(text(o.obs_id)))
}
function pathSource(path: RecordValue) { return rows(path.source_assertions) }
function pathTitle(path: RecordValue, index: number) {
  if (path.channel) return friendly(path.channel)
  const first = routeNodes(path)[0]
  return first?.label ?? `观测路径 ${index + 1}`
}
</script>
<template>
  <section class="panel proof-panel"><header class="panel-header"><div><span class="eyebrow">EXPLAINED</span><h2>候选与推理依据</h2></div><span class="tag" :class="rootkgd ? 'tag--purple' : 'tag--blue'">{{ rootkgd ? 'RootKGD' : '统一约束推理' }}</span></header>
    <div class="candidate-comparison"><div class="candidate-group-heading"><strong>{{ topRankCount > 1 ? `${topRankCount} 个首位同分候选` : rootkgd ? '当前结构比较结果' : '当前候选解释' }}</strong><span>{{ rootkgd ? `${candidates.length} 个结构比较候选` : `${supported.length} 个获支持候选` }}</span></div><label v-if="selected" class="candidate-switcher"><span>查看候选成员</span><select :value="selected.candidate_id" aria-label="查看候选解释" @change="emit('candidate', ($event.target as HTMLSelectElement).value)"><option v-for="candidate in candidates" :key="text(candidate.candidate_id)" :value="text(candidate.candidate_id)">{{ candidate.rank ? (candidate.rank === 1 && topRankCount > 1 ? '首位并列' : `第 ${candidate.rank} 位`) : '未列名次' }} · {{ candidateName(candidate) }}</option></select></label><details class="candidate-comparison-details"><summary>比较全部候选与{{ rootkgd ? '结构分数' : '解释代价' }}</summary><div class="comparison-heading"><span>{{ rootkgd ? '候选' : '完整 / 部分 / 未获支持均保留' }}</span><span>{{ rootkgd ? '结构分数 ↑' : '总代价 J ↓' }}</span></div><button v-for="candidate in visibleCandidates" :key="text(candidate.candidate_id)" class="candidate-row" :class="{ selected: selected?.candidate_id === candidate.candidate_id, unsupported: candidate.eligible_for_ranking !== true }" @click="emit('candidate', text(candidate.candidate_id))"><span class="candidate-rank">{{ candidate.rank ? String(candidate.rank).padStart(2,'0') : '—' }}</span><span class="grow"><strong>{{ candidateName(candidate) }}</strong><small>{{ candidate.eligible_for_ranking === true ? (!candidate.rank ? '支持（本次未列名次）' : supported.filter((c) => c.rank === candidate.rank).length > 1 ? (rootkgd ? '结构分数并列' : '并列支持') : (rootkgd ? '结构比较' : '存在支持')) : candidate.status === 'partial' ? '部分匹配' : candidate.status === 'insufficient_evidence' ? '证据不足' : '未形成完整支持' }}</small></span><b>{{ rootkgd ? number(candidate.score) : number(record(candidate.scoring_details).total_cost) }}</b><IconArrowRight /></button><button v-if="supported.length && supported.length < candidates.length" class="other-candidates" @click="showOtherCandidates = !showOtherCandidates">{{ showOtherCandidates ? '收起未获支持候选' : `同时检查 ${candidates.length - supported.length} 个未获支持候选` }}</button></details><p class="score-caption">{{ rootkgd ? '分数衡量图传播结构与实测贡献的相容性，不是概率。' : '同一问题内，代价越低越相容；同分保留并列，不是概率。' }}</p></div>
    <div v-if="!selected" class="empty-state empty-state--compact"><IconQuestionCircle class="empty-state__icon" /><h3>{{ normalGateClosed(result) ? '本窗口不启动候选排名' : '当前没有可评估候选' }}</h3><p>{{ normalGateClosed(result) ? '未越过配套正常参考的异常门。左侧保留完整窗口、残差能量、正常上限与52通道观测。' : '检查输入与图谱场景、主体绑定，以及所需特征是否存在。' }}</p></div>
    <div v-else class="candidate-explanation"><div class="explanation-heading"><span class="section-kicker">{{ rootkgd ? '为什么排在这里' : selected.eligible_for_ranking ? '为什么支持这个候选' : '为什么尚不支持这个候选' }}</span><h3>{{ candidateName(selected) }}</h3><p v-if="rootkgd">沿实际图关系传播到测量通道，再与完整贡献向量比较。下面显示本次实际路径与分数分解。</p><p v-else-if="selected.eligible_for_ranking">{{ completeChecks.length }} 个联合现象完整成立，{{ supportIds.length }} 项观测参与支持。{{ missingIds.length ? '部分替代表现仍缺测，见下方。' : isPattern ? '当前结果解释图案类别；制造原因需要其他知识与观测。' : '仍需额外观测区分具体原因。' }}</p><p v-else>当前观测没有满足该候选所需的完整支持，或与必要条件冲突。逐项检查如下。</p></div>
      <div v-if="!rootkgd" class="reason-summary"><div><strong>{{ supportIds.length }}</strong><span>支持观测</span></div><div :class="{ danger: conflictIds.length }"><strong>{{ conflictIds.length }}</strong><span>冲突条件</span></div><div :class="{ warning: missingIds.length }"><strong>{{ missingIds.length }}</strong><span>尚缺条件</span></div><div><strong>{{ number(costs.total_cost) }}</strong><span>总代价 J</span></div></div>
      <div v-else class="rootkgd-summary"><div><span>余弦相似度</span><strong>{{ number(costs.cosine_similarity) }}</strong></div><div><span>覆盖的贡献质量</span><strong>{{ number(costs.covered_contribution_mass) }}</strong></div><div><span>传播熵</span><strong>{{ number(costs.propagation_entropy) }}</strong></div><div><span>有效通道</span><strong>{{ costs.active_channel_count ?? '—' }}</strong></div></div>
      <section v-if="checks.length" class="joint-checks"><div class="section-heading"><h3>联合条件如何成立</h3><span class="count-label">{{ checks.length }} 项期待</span></div><details v-for="(check, index) in checks" :key="text(check.rule_id, String(index))" class="joint-check" :open="check.observed_value === true || check.selected_signature_value === true || !selected.eligible_for_ranking"><summary><span class="check-symbol" :class="check.observed_value === true ? 'yes' : check.observed_value === false ? 'no' : 'unknown'"><IconCheck v-if="check.observed_value === true" /><IconClose v-else-if="check.observed_value === false" /><IconQuestionCircle v-else /></span><span class="grow"><strong>{{ conditionName(check.pattern_id) }}</strong><small>{{ friendly(check.mode) }} · {{ check.observed_value === true ? '联合成立' : check.observed_value === false ? '存在冲突' : '尚未完整观测' }}</small></span></summary><div class="joint-check__body"><p v-if="checkExpression(check)" class="joint-expression">{{ checkExpression(check) }}</p><button v-for="fact in checkFacts(check)" :key="text(fact.predicate_id)" class="condition-row" :class="{ focused: factFocused(fact), violated: fact.value === false }" :disabled="!texts(fact.source_obs_ids).length" @click="focusFact(fact)"><span class="condition-truth" :class="fact.value === true ? 'yes' : fact.value === false ? 'no' : 'unknown'">{{ truthLabel(fact.value) }}</span><span class="grow"><strong>{{ factDescription(fact,names) }}</strong><small>条件 {{ conditionExpected(fact) }}</small><em v-if="fact.reason">{{ humanReason(fact.reason) }}</em></span><b>{{ rows(fact.actual_values).length || Array.isArray(fact.actual_values) && fact.actual_values.length ? formatValue(fact.actual_values) : '缺测' }}</b></button><p v-if="check.scope_valid === false" class="error-text">相关观测不属于允许的联合范围，不能合并证明。</p><details v-if="checkSources(check).length" class="check-source"><summary><IconFile /> 查看这条规则的资料依据</summary><article v-for="source in checkSources(check)" :key="text(source.assertion_id)"><span class="tag">{{ friendly(source.origin) }}</span><p>{{ source.text }}</p><small>{{ source.locator || '来源位置保存在图谱包中' }} · {{ friendly(source.parameter_origin) }}</small></article></details></div></details></section>
      <section v-if="paths.length" class="path-explanations"><div class="section-heading"><h3>{{ rootkgd ? '实际通道传播路径' : '从观测到候选的路径' }}</h3><span class="count-label">{{ paths.length }} 条</span></div><p v-if="!rootkgd" class="path-note">每条路径是联合证明的一部分，需要同组条件同时成立。</p><div v-for="(group, groupIndex) in pathGroups" :key="groupIndex" class="path-group"><div v-if="group.length > 1" class="path-group-label">联合证明 {{ groupIndex + 1 }} · {{ group.length }} 条观测路径</div><details v-for="(path, pathIndex) in group" :key="text(path.path_id, String(pathIndex))" class="reasoning-path" :open="pathIndex === 0 && groupIndex === 0"><summary><IconRelation /><span>{{ pathTitle(path,pathIndex) }}</span><small>{{ rootkgd ? `贡献 ${number(path.observed_contribution,3)}` : `${texts(path.required_joint_fact_ids).length} 项联合事实` }}</small></summary><div class="reasoning-path__body"><div v-if="routeNodes(path).length" class="proof-route"><template v-for="(node,index) in routeNodes(path)" :key="`${node.id}/${index}`"><IconArrowRight v-if="index" /><span :class="{ candidate: node.isCandidate }">{{ node.label }}</span></template></div><div v-if="pathObservation(path).length" class="path-observations"><button v-for="observation in pathObservation(path)" :key="text(observation.obs_id)" @click="emit('focus',text(observation.obs_id))"><IconArrowRight />{{ featureNames[text(observation.feature_id)] || friendly(observation.feature_id) }}：{{ formatValue(observation.value) }}</button></div><p v-if="rootkgd" class="path-note">图传播信号 {{ number(path.propagated_signal) }} · 实测贡献 {{ number(path.observed_contribution) }}</p><details v-if="pathSource(path).length" class="check-source"><summary><IconFile /> {{ pathSource(path).length }} 项实际来源断言</summary><article v-for="(source,index) in pathSource(path)" :key="text(source.assertion_id,String(index))"><span class="tag">{{ friendly(source.origin,'来源') }}</span><p>{{ source.text }}</p><small>{{ source.locator || '源记录' }}</small></article></details><details class="technical"><summary>路径引用与联合事实</summary><pre>{{ JSON.stringify({ path_id: path.path_id, nodes: path.nodes, source_edge_views: path.source_edge_views, required_joint_fact_ids: path.required_joint_fact_ids, support_obs_ids: path.support_obs_ids },null,2) }}</pre></details></div></details></div></section>
      <section v-if="missingIds.length" class="missing-conditions"><h3><IconQuestionCircle /> 还缺什么</h3><p>{{ selected.eligible_for_ranking ? '以下含未观测的替代表现。当前支持不要求它们全部成立，但补充测量有助于区分候选。' : '这些条件没有得到有效观测。缺测与明确阴性不同。' }}</p><ul><li v-for="id in missingIds" :key="id">{{ conditionName(id) }}</li></ul></section>
      <details class="scoring-details"><summary>{{ rootkgd ? '结构分数如何组成' : 'U / C / A / J 如何计算' }}</summary><template v-if="!rootkgd"><div class="cost-equation">J = U + {{ costs.conflict_weight ?? 2 }} C + {{ costs.assumption_weight ?? .25 }} A</div><dl><dt>未解释观测 U</dt><dd>{{ number(costs.unexplained_loss) }}</dd><dt>冲突代价 C</dt><dd>{{ number(costs.conflict_loss) }}</dd><dt>假设成本 A</dt><dd>{{ number(costs.assumption_cost) }}</dd><dt>总解释代价 J</dt><dd>{{ number(costs.total_cost) }}</dd></dl><p>候选使用相同分母与策略；重复来源不会增加投票。</p></template><template v-else><dl><dt>未覆盖贡献</dt><dd>{{ number(costs.uncovered_contribution_mass) }}</dd><dt>覆盖惩罚</dt><dd>{{ number(costs.coverage_penalty) }}</dd><dt>熵惩罚</dt><dd>{{ number(costs.entropy_penalty) }}</dd><dt>结构分数</dt><dd>{{ number(costs.structural_score ?? selected.score) }}</dd></dl><p>{{ costs.formula }}</p></template></details>
      <details v-if="rows(knowledge.hypotheses).length" class="context-graph"><summary><IconRelation /> 在完整知识图谱中定位当前候选</summary><SemanticGraph :knowledge="knowledge" :selected-id="text(selected.candidate_id)" :highlighted-ids="activeGraphIds" compact @select="(id) => { if (candidates.some((c) => c.candidate_id === id)) emit('candidate',id) }" /></details>
      <details class="technical"><summary>完整后端证明与原始结果</summary><pre>{{ JSON.stringify(result,null,2) }}</pre></details>
    </div>
  </section>
</template>
<style scoped>
